import {copy} from './music.js';
import {sectionAt} from './sections.js';
import {planSectionFill,FILL_STYLES,FILL_DEFAULTS} from './section-transition.js';
const $=s=>document.querySelector(s),escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function createSectionFillUI({getProject,getRevision,getSelected,commit,protectedChange,modal,toast}){
 let flow=0;
 return function show(id=getSelected()){
  const before=copy(getProject()),at=getRevision(),selection=getSelected(),ticket=++flow;let section;
  try{section=sectionAt(before,id)}catch(e){return toast(e.message)}
  const drums=before.tracks.filter(t=>t.kind==='drum');if(!drums.length)return toast('当前工程没有鼓轨，请先添加鼓轨。');let result,busy=false;
  modal('段尾过门 · 让下一段更好进入',`<div class="fill-form"><p><strong>${escape(section.name)}</strong> · 第 ${section.start/4+1} 小节起，共 ${section.length/4} 小节。只替换此段末尾所选鼓轨，旋律和其他时间保持。</p><div class="fill-presets">${Object.entries(FILL_STYLES).map(([key,name])=>`<button class="quiet" data-fill-style="${key}"><strong>${name}</strong><small>${key==='gentle'?'八分节奏 · 一点军鼓提示':key==='rise'?'末两拍十六分 · 推向下一段':'最后半拍留白 · 不是自动静音'}</small></button>`).join('')}</div><div class="section-fields"><label for="fill-bars">段末范围<select id="fill-bars" aria-label="段末范围"><option value="1">最后 1 小节</option><option value="2" ${section.length<8?'disabled':''}>最后 2 小节</option></select></label><label for="fill-energy">能量（30–100）<input id="fill-energy" type="number" min="30" max="100" step="1" value="70"></label><label for="fill-seed">变奏种子<input id="fill-seed" type="number" min="1" max="2147483647" step="1" value="1"></label></div><fieldset class="fill-tracks"><legend>替换哪些现有鼓轨</legend>${drums.map(t=>`<label class="check-label"><input type="checkbox" data-fill-track="${t.id}" checked>${escape(t.name)}${t.muted?' · 轨道已静音':''}${t.solo?' · 独奏':''}</label>`).join('')}</fieldset><label class="check-label"><input id="fill-gaps" type="checkbox">在空白处新建音块（新块不静音；仍保留轨道 M / S）</label><div id="fill-summary" class="section-summary" aria-live="polite"></div><div id="fill-grid"></div><div id="fill-error" role="status" class="export-progress"></div><details class="modal-notice"><summary>哪些保持，哪些会改变？</summary><p>这是本地规则鼓过门，不调用 LLM，不分析原曲和声，也不自动播放。同类鼓轨采用相同节奏，力度随轨道、种子和能量稳定变化；不是新增音乐风格。</p><p>只替换所选轨道在段尾窗口内的音符；跨界持音保留窗外片段，必要时重新起音并限制切片微偏移，过短片段整组拒绝。旧音块布局 / 静音不动；改变的共享块局部独立，源与其他引用保持。只有明确允许才新建空白处的独立音块。保留音色 / 混音 / 段落 / 练习范围 / 工程长度 / BPM / 调性 / 摇摆；全局摇摆仍影响实际起音。最后半拍留白仅指新鼓型，其他轨、释放尾音仍可继续。</p><p>先静态检查，再保存应用前版本，一次撤销。关闭窗口不改变音乐；预设只更新草稿，种子只改变力度，不改变格点。</p></details></div>`,'<button class="quiet" data-close>取消</button><button class="accent" id="fill-apply">备份并应用段尾过门</button>');
  const d=$('#modal'),root=$('.fill-form');let style=FILL_DEFAULTS.style;d.addEventListener('close',()=>{if(ticket===flow)++flow},{once:true});
  const revisionGuard=()=>{if(at!==getRevision()||selection!==getSelected())throw Error('工程或段落选择已改变，请重新打开过门助手。')};
  const guard=()=>{revisionGuard();if(ticket!==flow||!root.isConnected||!d.open)throw Error('窗口已改变，没有应用旧过门。')};
  const fail=e=>{if(root.isConnected){$('#fill-error').textContent=e.message;$('#fill-apply').disabled=true}else toast(e.message)};
  function update(){result=null;try{guard();result=planSectionFill(before,id,{trackIds:[...root.querySelectorAll('[data-fill-track]:checked')].map(n=>n.dataset.fillTrack),controls:{style,bars:+$('#fill-bars').value,energy:$('#fill-energy').value===''?NaN:+$('#fill-energy').value,seed:$('#fill-seed').value===''?NaN:+$('#fill-seed').value,fillGaps:$('#fill-gaps').checked}});const r=result.report;
    root.querySelectorAll('[data-fill-style]').forEach(n=>{n.classList.toggle('active',n.dataset.fillStyle===style);n.setAttribute('aria-pressed',n.dataset.fillStyle===style)});
    $('#fill-summary').innerHTML=`<span class="eyebrow">静音草稿 · ${FILL_STYLES[style]}</span><h3>第 ${r.start/4+1}${r.end/4===r.start/4+1?'':'–'+r.end/4} 小节 · ${r.tracks.length} 条鼓轨</h3><div class="performance-badges"><span>移除 ${r.removedNotes} · 新增 ${r.addedNotes} 音符</span><span>切片 ${r.trimmedNotes} 长音</span><span>新建 ${r.newClips} 音块</span><span>局部独立 ${r.detached} 共享块</span></div><p>窗外音乐与旋律保持，当前工程尚未改变。${r.limitedTiming?`${r.limitedTiming} 个切片微偏移受新边界限制。`:''}</p>`;
    const cells=result.controls.bars*16;$('#fill-grid').innerHTML=`<div class="fill-grid" role="img" aria-label="段尾过门名义节奏预览，每格十六分音符，斜纹代表所在音块静音">${r.tracks.map(row=>{const track=result.project.tracks.find(t=>t.id===row.id),hits=track.notes.filter(n=>n.start>=r.start&&n.start<r.end);return`<div class="fill-grid-row"><strong>${escape(row.name)}<small>新增 ${row.added}${row.mutedHits?' · 块静音 '+row.mutedHits:''}</small></strong><div class="fill-cells" style="--fill-cells:${cells}">${Array.from({length:cells},(_,i)=>{const beat=r.start+i/4,n=hits.find(n=>Math.abs(n.start-beat)<.00005),clip=track.clips.find(c=>beat>=c.start&&beat<c.start+c.length);return`<span class="fill-cell ${n?'hit':''} ${clip?.muted?'is-muted':''} ${i%4===0?'beat':''}" title="第 ${+(beat/4+1).toFixed(4)} 小节${n?' · 力度 '+n.velocity:' · 无起音'}" style="--hit-strength:${n?n.velocity/127:0}"></span>`}).join('')}</div></div>`}).join('')}</div><p class="fill-caption">每格 1/16 音符；亮格是名义起音，斜纹是块静音。轨道 M / S 和摇摆不在格点里模拟。</p>`;$('#fill-error').textContent='';$('#fill-apply').disabled=busy;
   }catch(e){$('#fill-summary').textContent='草稿未通过检查，没有修改音乐。';$('#fill-grid').innerHTML='';fail(e)}}
  root.querySelectorAll('[data-fill-style]').forEach(n=>n.onclick=()=>{if(!busy){style=n.dataset.fillStyle;update()}});root.querySelectorAll('input,select').forEach(n=>n.oninput=()=>{if(!busy)update()});
  $('#fill-apply').onclick=async()=>{try{guard();if(!result||busy)throw Error('请先得到合法过门预览');const planned=result;busy=true;root.querySelectorAll('input,select,button').forEach(n=>n.disabled=true);$('#fill-apply').disabled=true;$('#fill-error').textContent='正在保存过门前版本，工程尚未改变…';let applied=false;
    await protectedChange(({fallback=false}={})=>{try{fallback?revisionGuard():guard();if(commit(planned.project)){applied=true;d.close();toast(`已应用 ${planned.controls.bars} 小节段尾过门 · ${planned.report.tracks.length} 鼓轨，可一次撤销。没有播放。`)}}catch(e){toast(e.message)}},'段尾过门前 · '+section.name);
    if(!applied&&root.isConnected&&d.open){busy=false;root.querySelectorAll('input,select,button').forEach(n=>n.disabled=false);if(section.length<8)$('#fill-bars option[value="2"]').disabled=true;update()}
   }catch(e){fail(e)}};update();
 };
}
